const module = angular.module("irtech.netcity.school.talents",
[
	"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
	"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components", "irtech.netcity.directive",
	"irtech.netcity.em.events.common"
]);

require("./studentevents/list/listEventsCtrl.js");
require("approot/global/directives/storageDirective.coffee");

module
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/studentevents/list/",
			{
				templateUrl: "/static/dist/app/school/talents/studentevents/list/template.html",
				controller: "ListStudentEventsCtrl"
			})
			.otherwise({
				templateUrl: "/static/dist/app/school/talents/studentevents/list/template.html",
				controller: "ListStudentEventsCtrl"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



