"use strict";

import EventsReferences from "approot/em/events/common/references.coffee";
import { UserEventViewModel } from "approot/em/events/common/model.coffee";
import Selectable from "approot/global/selectable";
import { EditUserEventController } from "approot/em/events/common/eventMember/editEventMemberCtrl.js";

angular
	.module("irtech.netcity.school.talents")
	.controller("ListStudentEventsCtrl", ($scope, $http, $q, $alerts, $routeParams, $dialogs, $appLoader, $uibModal) => {

		$scope.$parent.page = {
			title: language.Generic.MenuFolders.kFNCuratorPersonalPlan
		}

		$scope.userId = appContext.userId;

		$.extend($scope, {
			language: language,
			data: {
				events: [],
				viewEvents: [],
				awardEventType: null,
				eventStatus: "Future",
				refs: EventsReferences
			},
			state: {
				dataReady: false,
				emptyData: false,
				viewReady: true
			}
		});

		$scope.data.selection = new Selectable();
		$scope.filterEventListByFilter = () => {

			$scope.data.viewEvents = _.filter($scope.data.events, (eventMember) => {
				let show = true;
				if ($scope.data.eventStatus !== "All") {
					show = show && eventMember.eventInfo.getStatus() === $scope.data.eventStatus;
				}
				if ($scope.data.awardEventType) {
					show = show && eventMember.eventInfo.awardEventType.id === $scope.data.awardEventType;
				}
				return show;
			});
		};

		//редактировать участника
		$scope.edit = () => {
			const member = $scope.data.selection.selected;

			let modalInstance = $uibModal.open({
				templateUrl: '/static/dist/app/em/events/common/eventMember/template.html',
				controller: EditUserEventController,
				controllerAs: "ctrl",
				resolve: {
					eventMemberId: () => member.eventMemberId,
					user: () => {return {id: $scope.userId}},
					event: () => member.eventInfo,
					participiationInfo: () => member.participiationInfo
				}
			});

			modalInstance.result.then(() => { $scope.load(); });
		}

		//удалении данных об участии
		$scope.remove = () => {
			const member = $scope.data.selection.selected;

			$http.delete(`/webapi/users/${$scope.userId}/events`, {params: {eventMemberId: member.eventMemberId}})
			.then(() => { $scope.load();})
			.catch((response) => {
				$alerts.error(response.data.message, response.data.details);
			});
		};

		//загрузка данных
		$scope.load = () => {
			$http.get(`/webapi/users/${$scope.userId}/events`)
			.then((response) => {
				$scope.data.events = _.map(response.data, (dto) => new UserEventViewModel(dto));
				$scope.filterEventListByFilter();
				$scope.state.viewReady = true;
				$scope.state.dataReady = true;
				$scope.state.emptyData = !$scope.data.events.length;
				$appLoader.hide();
			})
			.catch((response) => {
				//отображение в темплейте
				$scope.error = response.message || response.details || language.Generic.Common.kUnexpErr;
			});
		}

		$scope.load();
	});



